// Which workflows to watch. match = part of the workflow name (any case).
// staleHours = warn if it hasn't run for this long. mustBeOn = flag it if it's switched off.
return [{ json: {
  n8n: 'http://localhost:5678',
  v: 'v24.0',
  appId: '2155131125076167',
  warnDays: 14,   // email when the Meta token has this many days left
  urgentDays: 5,
  watch: [
    { match: 'social poster', label: 'Social poster', mustBeOn: true, staleHours: 2, every: 'every 30 minutes' },
    { match: 'outreach scout', label: 'Outreach scout', mustBeOn: true, staleHours: 28, every: 'every morning at 7' },
    { match: 'social analytics', label: 'Analytics puller', mustBeOn: true, staleHours: 28, every: 'every morning at 6' },
    { match: 'photo submissions', label: 'Photo submissions', mustBeOn: false },
    { match: 'dm inbox', label: 'DM replies', mustBeOn: false },
  ],
} }];

// One job per workflow to check: every watched workflow, plus any other active one (errors only).
const s = $('Settings').first().json;
const list = $json.data;
const api = `${s.n8n}/api/v1`;
const jobs = [];
if (Array.isArray(list)) {
  for (const wf of list) {
    if (wf.id === $workflow.id) continue;
    const w = s.watch.find(x => String(wf.name).toLowerCase().includes(x.match)) || null;
    if (!wf.active && !(w && w.mustBeOn)) continue;
    jobs.push({ id: wf.id, name: wf.name, label: w ? w.label : wf.name, active: !!wf.active, watch: w,
      runsUrl: `${api}/executions?workflowId=${wf.id}&limit=100`,
      errUrl: `${api}/executions?workflowId=${wf.id}&status=error&limit=1&includeData=true` });
  }
}
// Keep one harmless item so the rest of the run (token check, heartbeat) still happens.
if (!jobs.length) jobs.push({ dummy: true, apiError: list ? '' : ($json.message || $json.error?.message || JSON.stringify($json).slice(0, 200)),
  runsUrl: `${s.n8n}/healthz`, errUrl: `${s.n8n}/healthz` });
return jobs.map(json => ({ json }));

// Turn each workflow's recent runs into one plain-English health row.
const s = $('Settings').first().json;
const jobs = $('Workflow jobs').all();
const runsAll = $('n8n: recent runs').all();
const now = DateTime.now().setZone('America/Chicago');
const when = iso => DateTime.fromISO(iso).setZone('America/Chicago').toFormat("ccc LLL d, h:mm a");
const bad = st => st === 'error' || st === 'crashed';
const out = [];
$input.all().forEach((it, i) => {
  const j = jobs[i].json;
  if (j.dummy) {
    if (j.apiError !== undefined && j.apiError !== '') out.push({ check: 'n8n-api', label: 'Health check', status: 'fail', email: 'yes',
      detail: `The health check can't read your n8n workflows. The n8n API key may be missing or wrong. n8n said: ${j.apiError}`,
      link: `${s.n8n}/settings/api` });
    return;
  }
  const runs = (runsAll[i].json.data || []).filter(r => r.startedAt)
    .sort((a, b) => String(b.startedAt).localeCompare(String(a.startedAt)));
  const done = runs.filter(r => r.status !== 'running' && r.status !== 'waiting' && r.status !== 'new');
  const latest = done[0];
  const day = now.minus({ hours: 24 });
  const errs = done.filter(r => bad(r.status) && DateTime.fromISO(r.startedAt) > day);
  const e = (it.json.data || [])[0];
  const msg = e && e.data && e.data.resultData
    ? [e.data.resultData.error && e.data.resultData.error.message, e.data.resultData.lastNodeExecuted && `(step: ${e.data.resultData.lastNodeExecuted})`].filter(Boolean).join(' ')
    : '';
  const w = j.watch || {};
  const row = { check: 'wf:' + j.id, label: j.label, link: `${s.n8n}/workflow/${j.id}` };
  if (w.mustBeOn && !j.active) {
    Object.assign(row, { status: 'fail', email: 'yes', detail: `${j.label} is switched off in n8n, so it isn't running. Open it and click Publish.` });
  } else if (latest && bad(latest.status)) {
    Object.assign(row, { status: 'fail', email: 'yes', link: `${s.n8n}/workflow/${j.id}/executions/${latest.id}`,
      detail: `${j.label} failed on ${when(latest.startedAt)}.${msg ? ' ' + msg.slice(0, 220) : ''}` });
  } else if (w.staleHours && (!latest || DateTime.fromISO(latest.startedAt) < now.minus({ hours: w.staleHours }))) {
    Object.assign(row, { status: 'warn', email: 'no',
      detail: latest ? `${j.label} hasn't run since ${when(latest.startedAt)} (it runs ${w.every}). n8n or the Mac was probably off or asleep.`
                     : `${j.label} hasn't run yet (it runs ${w.every}).` });
  } else if (errs.length) {
    Object.assign(row, { status: 'warn', email: 'no', link: `${s.n8n}/workflow/${j.id}/executions/${errs[0].id}`,
      detail: `${j.label} failed ${errs.length} time${errs.length > 1 ? 's' : ''} in the last day, but its latest run worked.` });
  } else {
    Object.assign(row, { status: 'ok', email: 'no',
      detail: latest ? `${j.label} is fine. Last run ${when(latest.startedAt)}.` : `${j.label} is on and has no runs yet.` });
  }
  out.push(row);
});
return out.map(json => ({ json }));

// Add the Meta token check and the heartbeat, then keep "since" steady while a problem lasts.
const s = $('Settings').first().json;
const now = DateTime.now().setZone('America/Chicago');
const fmt = d => d.setZone('America/Chicago').toFormat('ccc LLL d');
const rows = $('Check workflows').all().map(i => ({ ...i.json }));
const explorer = 'https://developers.facebook.com/tools/explorer';

// Meta token: does it still work, and when does it end?
const me = $('Meta: token works').first().json;
const info = $('Meta: token expiry').first().json;
const tok = { check: 'meta-token', label: 'Meta token (Open Frame Page)', link: explorer };
if (me.error) {
  const dead = me.error.code === 190 || me.error.type === 'OAuthException' && me.error.code !== 4 && me.error.code !== 17;
  Object.assign(tok, dead
    ? { status: 'fail', email: 'yes', detail: `The Meta token stopped working, so posts and stats are blocked until it's replaced. Meta said: ${me.error.message}` }
    : { status: 'warn', email: 'no', detail: `Couldn't reach Meta to test the token. Meta said: ${me.error.message}` });
} else {
  const secs = Number(info && info.expires_in);
  if (secs > 0) {
    const end = now.plus({ seconds: secs });
    const days = Math.floor(secs / 86400);
    if (days <= s.urgentDays) Object.assign(tok, { status: 'fail', email: 'yes', detail: `The Meta token runs out on ${fmt(end)} (${days} day${days === 1 ? '' : 's'} left). Make a new one now or posting stops.` });
    else if (days <= s.warnDays) Object.assign(tok, { status: 'warn', email: 'yes', detail: `The Meta token runs out on ${fmt(end)} (${days} days left). Make a new one before then.` });
    else Object.assign(tok, { status: 'ok', email: 'no', detail: `Token works. It runs out on ${fmt(end)}.` });
  } else {
    Object.assign(tok, { status: 'ok', email: 'no', detail: 'Token works. Meta gives it no end date, so it only needs replacing if it stops working (checked every hour).' });
  }
}
rows.push(tok);

// Heartbeat: the Hub warns you if this stops updating (Mac off or n8n stopped).
rows.push({ check: 'heartbeat', label: 'n8n on your Mac', status: 'ok', email: 'no', detail: 'Health check ran.', link: s.n8n });

// "since" = when the current problem started. The Hub emails once per check + since + status.
const st = $getWorkflowStaticData('global');
st.since = st.since || {};
const iso = now.toISO();
for (const r of rows) {
  if (r.status === 'ok') { delete st.since[r.check]; r.since = ''; }
  else r.since = st.since[r.check] = st.since[r.check] || iso;
  r.updated_at = iso;
}
return rows.map(json => ({ json }));
